/* Source: shared/lib/identity.js; buildPhoneCountryMenu. Generated by standalone-build.mjs. */
function buildPhoneCountryMenu(field){
    if(field.querySelector('[data-phone-country-menu]')) return;
    const menu=document.createElement('div');
    menu.className='phone-field__menu';
    menu.hidden=true;
    menu.setAttribute('data-phone-country-menu','');
    const search=document.createElement('input');
    search.className='input phone-field__search';
    search.type='search';
    search.placeholder='ค้นหาประเทศ';
    search.setAttribute('data-phone-country-search','');
    const list=document.createElement('ul');
    list.className='phone-field__list';
    list.setAttribute('role','listbox');
    PHONE_COUNTRIES.forEach(([code,name,dial,flag]) => {
      const item=document.createElement('li');
      const button=document.createElement('button');
      button.type='button';
      button.className='phone-field__option';
      button.setAttribute('role','option');
      button.dataset.phoneCountry=code;
      button.dataset.phoneDial=dial;
      button.dataset.phoneFlag=flag;
      button.dataset.phoneName=name;
      button.innerHTML='<span class="phone-field__option-flag">'+flag+'</span>'+
        '<span class="phone-field__option-name">'+name+'</span>'+
        '<span class="phone-field__option-dial">+'+dial+'</span>';
      item.append(button);
      list.append(item);
    });
    menu.append(search,list);
    field.append(menu);
  }

/* Source: shared/lib/intake.js; kraneHandle_intake_durationStep. Generated by standalone-build.mjs. */
function kraneHandle_intake_durationStep(e, intakeDurationStep) {
      const screen=intakeDurationStep.closest('.screen');
      const input=screen?.querySelector('input[data-intake-role="duration"]');
      if(!input) return true;
      input.value=String(Math.min(99,Math.max(1,(Number(input.value) || 1)+Number(intakeDurationStep.dataset.intakeDurationStep || 0))));
      input.dispatchEvent(new Event('input',{bubbles:true}));
      syncIntakeDropdownContinue(screen);
      return true;

  return false;
}

/* Source: shared/lib/intake.js; kraneHandle_intake_durationUnit. Generated by standalone-build.mjs. */
function kraneHandle_intake_durationUnit(e, intakeDurationUnit) {
      const screen=intakeDurationUnit.closest('.screen');
      screen?.querySelectorAll('[data-intake-duration-unit]').forEach(option => {
        option.setAttribute('aria-selected',String(option===intakeDurationUnit));
      });
      saveIntakeDraft();
      syncIntakeDropdownContinue(screen);
      return true;

  return false;
}

/* Source: shared/lib/orders.js; kraneHandle_orders_selectBank. Generated by standalone-build.mjs. */
function kraneHandle_orders_selectBank(e, bank) {
      bank.closest('.bank-grid').querySelectorAll('[data-bank-select]').forEach(b => b.classList.toggle('is-selected', b === bank));
      showActionToast('เลือกธนาคารแล้ว');
      return true;

  return false;
}

